    m = re.findall(r'```json\s*([\s\S]*?)\s*```', txt)
    for block in m:
        try:
            data = json.loads(block)
            if isinstance(data, list):
                items.extend(data)
            elif isinstance(data, dict):
                if 'items' in data and isinstance(data['items'], list):
                    items.extend(data['items'])
